DROP TABLE IF EXISTS compliance_issues;
CREATE TABLE compliance_issues (
    id SERIAL PRIMARY KEY,
    sitekey TEXT NOT NULL,
    description TEXT,
    issue_date DATE
);
INSERT INTO compliance_issues (sitekey, description, issue_date)
SELECT 
    p.sitekey,
    'Plant is Non-Compliant. Document state: ' || COALESCE(p.docstate, 'Unknown') || ', Insurance state: ' || COALESCE(p.insurstate, 'Unknown') || ', Warranty state: ' || COALESCE(p.warrstate, 'Unknown'),
    CURRENT_DATE
FROM plants p
WHERE p.complyflag = 'Non-Compliant';
SELECT sitelabel FROM compliance_issues ci JOIN plants p ON ci.sitekey = p.sitekey WHERE cap_mw > 300;
